48	// Clone by hand: the common cases are tested one by one before the full match, whose jump table the CPU
49	// mispredicts when floats, objects and tuples alternate (as in an autograd graph's inner loops).
50	impl Clone for V {
51	    #[inline]
52	    fn clone(&self) -> V {
53	        if let V::Float(f) = self {
54	            return V::Float(*f);
55	        }
56	        if let V::Obj(o) = self {
57	            return V::Obj(o.clone());
58	        }
59	        if let V::Int(i) = self {
60	            return V::Int(*i);
61	        }
62	        if let V::Tuple(t) = self {
63	            return V::Tuple(t.clone());
64	        }
65	        self.clone_slow()
66	    }
67	}
68	impl V {
69	    #[inline(never)]
70	    fn clone_slow(&self) -> V {
71	        match self {
72	            V::Unbound => V::Unbound,
73	            V::None => V::None,
74	            V::Bool(x) => V::Bool(x.clone()),
75	            V::Int(x) => V::Int(x.clone()),
76	            V::Big(x) => V::Big(x.clone()),
77	            V::Float(x) => V::Float(x.clone()),
78	            V::Str(x) => V::Str(x.clone()),
79	            V::List(x) => V::List(x.clone()),
