966	pub fn parse_float(t: &str) -> Option<f64> {
967	    let t = t.trim();
968	    let l = t.to_ascii_lowercase();
969	    let body = l.trim_start_matches(['+', '-']);
970	    let neg = l.starts_with('-');
971	    let r = match body {
972	        "inf" | "infinity" => Some(f64::INFINITY),
973	        "nan" => Some(nan_obj()),
974	        _ => {
975	            if body.is_empty() || !body.chars().all(|c| c.is_ascii_digit() || matches!(c, '.' | 'e' | '+' | '-' | '_')) || body.starts_with('_') || body.ends_with('_') || body.contains("__") {
976	                return None;
977	            }
978	            if body.starts_with('e') || body.starts_with('.') && body.len() == 1 {
979	                return None;
980	            }
981	            let b = body.replace('_', "");
982	            b.parse::<f64>().ok()
983	        }
984	    }?;
985	    Some(if neg { -r } else { r })
