fn nan_cmp(body: &[Stmt]) -> Option<(usize, String)> {
    fn nan_text(e: &Ex) -> bool {
        matches!(e, Ex::Str(s) if matches!(s.trim().to_ascii_lowercase().as_str(), "nan" | "+nan" | "-nan"))
    }
    fn inf_text(e: &Ex) -> bool {
        matches!(e, Ex::Str(s) if matches!(s.trim().to_ascii_lowercase().as_str(), "inf" | "+inf" | "-inf" | "infinity" | "+infinity" | "-infinity"))
    }
    fn name_of(e: &Ex) -> Option<&str> {
        match e {
            Ex::Name(n) => Some(n),
            _ => None,
        }
    }
    fn nan_val(e: &Ex, nans: &HashSet<String>) -> bool {
        match e {
            Ex::Name(n) => nans.contains(n),
            Ex::Unary("-" | "+", a) => nan_val(a, nans),
            Ex::Call(f, args) => match f.as_ref() {
                Ex::Name(n) if n == "float" => args.iter().any(|a| matches!(a, Arg::Pos(x) if nan_text(x) || nan_val(x, nans))),
                _ => false,
            },
            Ex::Attr(r, n) => n == "nan" && matches!(r.as_ref(), Ex::Name(m) if m == "math" || m == "numpy"),
            _ => false,
        }
    }
    fn inf_val(e: &Ex, infs: &HashSet<String>) -> bool {
        match e {
            Ex::Name(n) => infs.contains(n),
            Ex::Unary("-" | "+", a) => inf_val(a, infs),
            Ex::Call(f, args) => match f.as_ref() {
                Ex::Name(n) if n == "float" => args.iter().any(|a| matches!(a, Arg::Pos(x) if inf_text(x) || inf_val(x, infs))),
                _ => false,
            },
            Ex::Attr(r, n) => n == "inf" && matches!(r.as_ref(), Ex::Name(m) if m == "math" || m == "numpy"),
            _ => false,
        }
    }
    fn int_val(e: &Ex) -> Option<i64> {
        match e {
            Ex::Int(s) => s.replace('_', "").parse().ok(),
            _ => None,
        }
    }
    fn zero(e: &Ex) -> bool {
        int_val(e) == Some(0) || matches!(e, Ex::Float(f) if *f == 0.0)
    }
    fn neg_num(e: &Ex) -> bool {
        match int_val(e) {
            Some(i) => i < 0,
            None => match e {
                Ex::Float(f) => *f < 0.0,
                Ex::Unary("-", a) => !matches!(a.as_ref(), Ex::Unary("-", _)),
                _ => false,
            },
        }
    }
    // Could this expression hold a NaN? NaN sources, anything computed from one, and the float
    // operations that make a NaN from finite operands (inf - inf, inf / inf, 0 * inf, 0 / 0, ...).
    fn may_val(e: &Ex, nans: &HashSet<String>, mays: &HashSet<String>, infs: &HashSet<String>) -> bool {
        match e {
            Ex::Name(n) => nans.contains(n) || mays.contains(n),
            Ex::Unary("-" | "+", a) => may_val(a, nans, mays, infs),
            Ex::Call(f, args) => match f.as_ref() {
                Ex::Name(n) if n == "float" => args.iter().any(|a| matches!(a, Arg::Pos(x) if may_val(x, nans, mays, infs))),
                // max/min pass a NaN through; abs, round and sum make a new one from it.
                Ex::Name(n) if matches!(n.as_str(), "max" | "min" | "abs" | "round" | "sum") => args.iter().any(|a| matches!(a, Arg::Pos(x) if may_val(x, nans, mays, infs))),
                Ex::Attr(r, _) if matches!(r.as_ref(), Ex::Name(m) if m == "math") => args.iter().any(|a| matches!(a, Arg::Pos(x) if may_val(x, nans, mays, infs))),
                _ => false,
            },
            Ex::Bin(op, a, b) => {
                if may_val(a, nans, mays, infs) || may_val(b, nans, mays, infs) {
                    return true;
                }
