                    "/" if (ia && ib) || (zero(a) && zero(b)) => true,
                    "*" if (ia && zero(b)) || (zero(a) && ib) => true,
                    "%" | "//" if ia => true,
                    "**" if zero(a) && neg_num(b) => true,
                    _ => false,
