    fn has_may(e: &Ex, nans: &HashSet<String>, mays: &HashSet<String>, infs: &HashSet<String>) -> bool {
        let mut found = false;
        walk_ex(e, &mut |x| found |= may_val(x, nans, mays, infs));
        found
    }
    fn container(e: &Ex) -> bool {
        matches!(e, Ex::List(_) | Ex::Tuple(_) | Ex::Set(_) | Ex::Dict(_))
            || matches!(e, Ex::Comp('l' | 's' | 'd', ..))
            || matches!(e, Ex::Call(f, _) if matches!(f.as_ref(), Ex::Name(n) if matches!(n.as_str(), "list" | "tuple" | "sorted" | "reversed")))
