    fn propagate(body: &[Stmt], params: &HashMap<String, Vec<String>>, nans: &mut HashSet<String>, mays: &mut HashSet<String>, infs: &mut HashSet<String>, conts: &mut HashSet<String>) {
        crate::dynpy::typing::walk_all(body, &mut |e, _| {
            let Ex::Call(f, args) = e else { return };
            let Ex::Name(fname) = f.as_ref() else { return };
            let Some(ps) = params.get(fname) else { return };
            for (i, a) in args.iter().enumerate() {
                let Arg::Pos(a) = a else { continue };
                let Some(p) = ps.get(i) else { continue };
                if may_val(a, nans, mays, infs) || (container(a) && has_may(a, nans, mays, infs)) {
                    mays.insert(p.clone());
                    conts.insert(p.clone());
                }
                if inf_val(a, infs) {
                    infs.insert(p.clone());
                }
            }
        });
    }
    fn scan(body: &[Stmt], nans: &mut HashSet<String>, mays: &mut HashSet<String>, infs: &mut HashSet<String>, conts: &mut HashSet<String>) {
        for s in body {
            match &s.st {
                St::Assign(ts, v) => {
                    if container(v) && has_may(v, nans, mays, infs) {
                        for t in ts {
                            if let Ex::Name(n) = t {
                                conts.insert(n.clone());
                            }
                        }
                    }
                    if may_val(v, nans, mays, infs) {
                        for t in ts {
                            if let Ex::Name(n) = t {
                                mays.insert(n.clone());
                            }
                        }
                    }
                    if nan_val(v, nans) {
                        for t in ts {
                            if let Ex::Name(n) = t {
                                nans.insert(n.clone());
                            }
                        }
                    }
                    if inf_val(v, infs) {
                        for t in ts {
                            if let Ex::Name(n) = t {
                                infs.insert(n.clone());
                            }
                        }
                    }
                    for t in ts {
                        if let Ex::Name(n) = t {
                            if let Ex::Name(m) = v {
                                if nans.contains(m) {
                                    nans.insert(n.clone());
                                }
                                if mays.contains(m) {
                                    mays.insert(n.clone());
                                }
                                if infs.contains(m) {
                                    infs.insert(n.clone());
                                }
                                if conts.contains(m) {
                                    conts.insert(n.clone());
                                }
                            }
                        }
                    }
                }
                St::AugAssign(t, _, v) => {
                    if let Ex::Name(n) = t {
                        if may_val(&Ex::Name(n.clone()), nans, mays, infs) || may_val(v, nans, mays, infs) {
                            mays.insert(n.clone());
                        }
