                        if container(v) && has_may(v, nans, mays, infs) {
                            if let Ex::Name(n) = t {
                                conts.insert(n.clone());
                            }
                        }
                        if may_val(v, nans, mays, infs) {
                            if let Ex::Name(n) = t {
                                mays.insert(n.clone());
                            }
                        }
                        if nan_val(v, nans) {
                            if let Ex::Name(n) = t {
                                nans.insert(n.clone());
                            }
                        }
                        if inf_val(v, infs) {
                            if let Ex::Name(n) = t {
                                infs.insert(n.clone());
                            }
                        }
                    }
                }
                St::For(t, it, _, _) => {
                    let may = match it {
                        Ex::Name(n) => conts.contains(n) || mays.contains(n) || nans.contains(n),
                        _ => container(it) && has_may(it, nans, mays, infs),
