                            }
                        });
                        mays.extend(names);
                    }
                }
                _ => {}
            }
            each_block(&s.st, &mut |b| scan(b, nans, mays, infs, conts));
        }
    }
    let mut nans: HashSet<String> = HashSet::new();
    let mut mays: HashSet<String> = HashSet::new();
    let mut infs: HashSet<String> = HashSet::new();
    let mut conts: HashSet<String> = HashSet::new();
